mapper.select:
SELECT cpsr.id, cpsr.park_org_id, cpsr.goods_id, cpsr.stock_id, cpsr.record_no, cpsr.stock_in_num, cpsr.stock_in_unit_price, cpsr.current_num, cpsr.current_average_price, cpsr.stock_type, cpsr.remark, cpsr.stock_mode, goods_type, goods_no, unit, goods_name, cpsr.create_by, cpsr.update_time FROM cus_pro_stock_record cpsr LEFT JOIN cus_pro_goods_manager cpgm ON cpsr.goods_id = cpgm.id WHERE cpsr.deleted = 0 AND cpgm.deleted = 0
and cpsr.park_org_id = #{query.parkOrgId}
and cpsr.park_org_id in
#{item}
and goods_name like concat('%',#{query.goodsName},'%')
and cpsr.stock_type = #{query.stockType}
and cpsr.create_time between #{query.stockInTimeStart} and #{query.stockInTimeEnd}
ORDER BY cpsr.create_time DESC
